// 1. Configuration Validation
int config_valid = 1;
if (dt_config.coarse_gain_a_m2_s_t < 0.0 || dt_config.fine_gain_a_m2_s_t < 0.0) config_valid = 0;
if (dt_config.max_dipole_a_m2 <= 0.0 || dt_config.max_dipole_slew_a_m2_per_cycle <= 0.0) config_valid = 0;
if (dt_config.minimum_field_t <= 0.0 || dt_config.maximum_field_t <= dt_config.minimum_field_t) config_valid = 0;
if (dt_config.max_sample_gap_s <= 0.0) config_valid = 0;
if (dt_config.stop_rate_t_s < 0.0 || dt_config.restart_rate_t_s < 0.0) config_valid = 0;
if (dt_config.fine_enter_rate_t_s < 0.0 || dt_config.fine_exit_rate_t_s < 0.0) config_valid = 0;
if (dt_config.filter_alpha < 0.0 || dt_config.filter_alpha > 1.0) config_valid = 0;
if (dt_config.required_good < 1U || dt_config.required_good > 20U) config_valid = 0;
if (dt_config.max_bad < 1U || dt_config.max_bad > 20U) config_valid = 0;

if (!(dt_config.stop_rate_t_s < dt_config.restart_rate_t_s &&
      dt_config.restart_rate_t_s <= dt_config.fine_enter_rate_t_s &&
      dt_config.fine_enter_rate_t_s < dt_config.fine_exit_rate_t_s)) {
    config_valid = 0;
}

// 2. Enable Check
if (!dt_input.enable) {
    dt_state.mode = DT_OFF;
    dt_state.good = 0;
    dt_state.bad = 0;
    dt_state.filter.initialized = 0;
    dt_output.mode = DT_OFF;
    dt_output.good = 0;
    dt_output.bad = 0;
    dt_output.saturation_mask = 0;
    dt_output.slew_mask = 0;
    dt_output.filter_primed_this_cycle = 0;
    dt_output.field_magnitude_t = 0.0;
    dt_output.rate_norm_t_s = 0.0;
    dt_output.rate_t_s = (adcs_vec3_t){0,0,0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0,0,0};
    return;
}

// Initialize output fields for this cycle
dt_output.filter_primed_this_cycle = 0;
dt_output.saturation_mask = 0;
dt_output.slew_mask = 0;

// 3. Sample Validity Initial Checks
adcs_vec3_t rate_copy = {0,0,0};
int sample_accepted = 1;

if (dt_input.field_body_t == NULL) {
    sample_accepted = 0;
} else if (!isfinite(dt_input.time_s)) {
    sample_accepted = 0;
} else if (!adcs_is_finite_vec3(dt_input.field_body_t)) {
    sample_accepted = 0;
} else {
    double b_mag = adcs_vec3_norm(dt_input.field_body_t);
    dt_output.field_magnitude_t = b_mag;
    if (b_mag < dt_config.minimum_field_t || b_mag > dt_config.maximum_field_t) {
        sample_accepted = 0;
    }
}

// Helper for rejection logic
auto reject_sample = [&]() {
    dt_state.bad++;
    dt_state.good = 0;
    dt_output.rate_t_s = (adcs_vec3_t){0,0,0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0,0,0};
    dt_output.rate_norm_t_s = 0.0;
    // Fault latch is implicit via bad count, no explicit mode change requested other than persistence
};

if (!sample_accepted || !config_valid) {
    reject_sample();
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    return;
}

// 4. Filter Update & Gap Check
adcs_bdot_state_t filter_copy = dt_state.filter;
adcs_status_t status = ADCS_OK;
int gap_exceeded = 0;

if (!filter_copy.initialized) {
    // First ever sample, prime it
    status = adcs_bdot_update(&filter_copy, dt_input.field_body_t, dt_input.time_s, 
                              dt_config.filter_alpha, &rate_copy);

    dt_state.mode = DT_COARSE;
    dt_state.good = 0;
    dt_state.filter = filter_copy; 

    dt_output.mode = DT_COARSE;
    dt_output.good = 0;
    dt_output.bad = dt_state.bad;
    dt_output.rate_t_s = (adcs_vec3_t){0,0,0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0,0,0};
    dt_output.rate_norm_t_s = 0.0;
    dt_output.filter_primed_this_cycle = 1;
    dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0,0,0}; // Clear stored dipole on prime
    return;
}

double dt_time = dt_input.time_s - filter_copy.previous_time_s;
if (dt_time > dt_config.max_sample_gap_s) {
    gap_exceeded = 1;
}

if (gap_exceeded) {
    // Reset and re-prime
    filter_copy.initialized = 0;
    status = adcs_bdot_update(&filter_copy, dt_input.field_body_t, dt_input.time_s, 
                              dt_config.filter_alpha, &rate_copy);

    dt_state.mode = DT_COARSE;
    dt_state.good = 0;
    dt_state.filter = filter_copy; 

    dt_output.mode = DT_COARSE;
    dt_output.good = 0;
    dt_output.bad = dt_state.bad;
    dt_output.rate_t_s = (adcs_vec3_t){0,0,0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0,0,0};
    dt_output.rate_norm_t_s = 0.0;
    dt_output.filter_primed_this_cycle = 1;
    dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0,0,0}; // Clear stored dipole on re-prime
    return;
}

// Normal update
status = adcs_bdot_update(&filter_copy, dt_input.field_body_t, dt_input.time_s, 
                          dt_config.filter_alpha, &rate_copy);

if (status != ADCS_OK) {
    reject_sample();
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    return;
}

dt_state.filter = filter_copy;
dt_state.filtered_rate_t_s = rate_copy;
double rate_norm = adcs_vec3_norm(&rate_copy);
dt_output.rate_norm_t_s = rate_norm;
dt_output.rate_t_s = rate_copy;

// 6. Mode Transition Logic
dt_mode_t next_mode = dt_state.mode;

if (dt_state.mode == DT_COARSE) {
    if (rate_norm <= dt_config.fine_enter_rate_t_s) {
        next_mode = DT_FINE;
    }
} else if (dt_state.mode == DT_FINE) {
    if (rate_norm > dt_config.fine_exit_rate_t_s) {
        next_mode = DT_COARSE;
    }
} else if (dt_state.mode == DT_COMPLETE) {
    if (rate_norm >= dt_config.restart_rate_t_s && rate_norm < dt_config.fine_exit_rate_t_s) {
        next_mode = DT_FINE;
    } else if (rate_norm >= dt_config.fine_exit_rate_t_s) {
        next_mode = DT_COARSE;
    } else {
        next_mode = DT_COMPLETE;
    }
}

if (dt_state.mode != DT_COMPLETE) {
    if (rate_norm <= dt_config.stop_rate_t_s) {
        dt_state.good++;
        if (dt_state.good >= dt_config.required_good) {
            next_mode = DT_COMPLETE;
        }
    } else {
        dt_state.good = 0;
    }
}

dt_state.mode = next_mode;
dt_output.mode = dt_state.mode;
dt_output.good = dt_state.good;
dt_output.bad = dt_state.bad;

// 7. Dipole Generation
adcs_actuator_command_t dipole_cmd;

if (dt_state.mode == DT_COMPLETE) {
    dt_output.dipole_a_m2 = (adcs_vec3_t){0,0,0};
    dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0,0,0};
    return;
}

double gain = (dt_state.mode == DT_FINE) ? dt_config.fine_gain_a_m2_s_t : dt_config.coarse_gain_a_m2_s_t;

status = adcs_bdot_dipole(dt_input.field_body_t, &rate_copy, gain, 
                          dt_config.max_dipole_a_m2, &dipole_cmd);

adcs_vec3_t limited_dipole = dipole_cmd.command;
unint32 saturation_mask = dipole_cmd.saturated_axes;
unint32 slew_mask = 0;
double max_slew = dt_config.max_dipole_slew_a_m2_per_cycle;

adcs_vec3_t diff = adcs_vec3_sub(&limited_dipole, &dt_state.previous_dipole_a_m2);

for (int i = 0; i < 3; i++) {
    double val = (i==0) ? diff.x : (i==1) ? diff.y : diff.z;
    if (fabs(val) > max_slew) {
        double sign = (val > 0) ? 1.0 : -1.0;
        double delta = sign * max_slew;
        double prev = (i==0) ? dt_state.previous_dipole_a_m2.x : (i==1) ? dt_state.previous_dipole_a_m2.y : dt_state.previous_dipole_a_m2.z;
        double new_val = prev + delta;

        if (i==0) limited_dipole.x = new_val;
        else if (i==1) limited_dipole.y = new_val;
        else limited_dipole.z = new_val;

        slew_mask |= (unint32)(1U << i);
    }
}

dt_output.dipole_a_m2 = limited_dipole;
dt_output.saturation_mask = saturation_mask;
dt_output.slew_mask = slew_mask;

dt_state.previous_dipole_a_m2 = limited_dipole;

