            break;
        case DT_COMPLETE:
            if (dt_output.rate_norm_t_s >= dt_config.restart_rate_t_s) {
                if (dt_output.rate_norm_t_s < dt_config.fine_exit_rate_t_s) {
                    dt_state.mode = DT_FINE;
                } else {
                    dt_state.mode = DT_COARSE;
                }
            }
            break;
        default:
            dt_state.mode = DT_COARSE;
            break;
    }

    // Check for entering COMPLETE
    if (dt_output.rate_norm_t_s <= dt_config.stop_rate_t_s) {
        dt_state.good++;
        if (dt_state.good >= dt_config.required_good) {
            dt_state.mode = DT_COMPLETE;
            dt_output.mode = DT_COMPLETE;

            // Complete commands zero
            dt_output.dipole_a_m2.x = 0.0;
            dt_output.dipole_a_m2.y = 0.0;
            dt_output.dipole_a_m2.z = 0.0;
            dt_output.saturation_mask = 0U;
            dt_output.slew_mask = 0U;

            // Clear stored dipole
            dt_state.previous_dipole_a_m2.x = 0.0;
            dt_state.previous_dipole_a_m2.y = 0.0;
            dt_state.previous_dipole_a_m2.z = 0.0;

            return;
        }
    } else {
        dt_state.good = 0;
    }

    // Generate Dipole for COARSE/FINE
    double gain = (dt_state.mode == DT_FINE) ? dt_config.fine_gain_a_m2_s_t : dt_config.coarse_gain_a_m2_s_t;
    adcs_actuator_command_t cmd;
    st = adcs_bdot_dipole(dt_input.field_body_t, &trial_rate, gain, dt_config.max_dipole_a_m2, &cmd);
    if (st != ADCS_OK) {
        dt_output.rate_t_s.x = 0.0;
        dt_output.rate_t_s.y = 0.0;
        dt_output.rate_t_s.z = 0.0;
        dt_output.rate_norm_t_s = 0.0;
        dt_output.dipole_a_m2.x = 0.0;
        dt_output.dipole_a_m2.y = 0.0;
        dt_output.dipole_a_m2.z = 0.0;
        dt_output.saturation_mask = 0U;
        dt_output.slew_mask = 0U;
        dt_output.filter_primed_this_cycle = 0;
        dt_output.field_magnitude_t = 0.0;
        dt_state.good = 0;
        dt_state.bad++;
        if (dt_state.bad >= dt_config.max_bad) {
            dt_state.mode = DT_FAULT;
            dt_output.mode = DT_FAULT;
        } else {
            dt_output.mode = dt_state.mode;
        }
        return;
    }

    // Apply Slew Limit
    adcs_vec3_t limited_dipole;
    uint32_t slew_mask = 0U;

    double max_slew = dt_config.max_dipole_slew_a_m2_per_cycle;

    // X axis
    {
        double prev_val = dt_state.previous_dipole_a_m2.x;
        double curr_val = cmd.command.x;
        double delta = curr_val - prev_val;
        double limited_val;
        if (delta > max_slew) {
            limited_val = prev_val + max_slew;
            slew_mask |= (1U << 0);
        } else if (delta < -max_slew) {
            limited_val = prev_val - max_slew;
            slew_mask |= (1U << 0);
        } else {
            limited_val = curr_val;
        }
        limited_dipole.x = limited_val;
    }

    // Y axis
    {
        double prev_val = dt_state.previous_dipole_a_m2.y;
        double curr_val = cmd.command.y;
        double delta = curr_val - prev_val;
        double limited_val;
        if (delta > max_slew) {
            limited_val = prev_val + max_slew;
            slew_mask |= (1U << 1);
        } else if (delta < -max_slew) {
            limited_val = prev_val - max_slew;
            slew_mask |= (1U << 1);
        } else {
            limited_val = curr_val;
        }
        limited_dipole.y = limited_val;
    }

    // Z axis
    {
        double prev_val = dt_state.previous_dipole_a_m2.z;
        double curr_val = cmd.command.z;
        double delta = curr_val - prev_val;
        double limited_val;
        if (delta > max_slew) {
            limited_val = prev_val + max_slew;
            slew_mask |= (1U << 2);
        } else if (delta < -max_slew) {
            limited_val = prev_val - max_slew;
            slew_mask |= (1U << 2);
        } else {
            limited_val = curr_val;
        }
        limited_dipole.z = limited_val;
    }

    dt_output.dipole_a_m2 = limited_dipole;
    dt_output.slew_mask = slew_mask;
    dt_output.saturation_mask = cmd.saturated_axes;
    dt_output.mode = dt_state.mode;

    // Update previous dipole
    dt_state.previous_dipole_a_m2 = limited_dipole;
    return;

rejected_sample:
    // Preserve filter and previous dipole
    // Publish zero
    dt_output.rate_t_s.x = 0.0;
    dt_output.rate_t_s.y = 0.0;
    dt_output.rate_t_s.z = 0.0;
    dt_output.rate_norm_t_s = 0.0;
    dt_output.dipole_a_m2.x = 0.0;
    dt_output.dipole_a_m2.y = 0.0;
    dt_output.dipole_a_m2.z = 0.0;
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    dt_output.filter_primed_this_cycle = 0;
    dt_output.field_magnitude_t = 0.0;

    // Clear good
    dt_state.good = 0;

    // Increment bad
    dt_state.bad++;

    // Latch FAULT
    if (dt_state.bad >= dt_config.max_bad) {
        dt_state.mode = DT_FAULT;
        dt_output.mode = DT_FAULT;
    } else {
        dt_output.mode = dt_state.mode;
    }

    return;
